def minJumps(arr: list[int]) -> int:
    n = len(arr)
    if n <= 1: return 0
    from collections import defaultdict, deque
    val_indices = defaultdict(list)
    for i, x in enumerate(arr): val_indices[x].append(i)
    q = deque([(0, 0)])
    visited = {0}
    while q:
        curr, steps = q.popleft()
        if curr == n - 1: return steps
        # Step to neighbors
        for nxt in (curr - 1, curr + 1):
            if 0 <= nxt < n and nxt not in visited:
                visited.add(nxt)
                q.append((nxt, steps + 1))
        # Teleport to all same values
        if arr[curr] in val_indices:
            for nxt in val_indices[arr[curr]]:
                if nxt not in visited:
                    visited.add(nxt)
                    q.append((nxt, steps + 1))
            del val_indices[arr[curr]]  # Greedy purge to avoid O(N^2) cycles
    return -1

